// Generated security helpers for customView
import { eq, and, isNull, type SQL } from 'drizzle-orm';
import type { Context } from 'hono';
import { customView } from './schema';
import type { AppContext } from '../../lib/types';
export { customView };

/**
 * Firewall conditions for customView
 * Exception resource (soft-delete only)
 */
export function buildFirewallConditions(ctx: AppContext, _db?: unknown, opts?: { skipTenantScopes?: boolean }): SQL | undefined {
  return isNull(customView.deletedAt);
}

/**
 * Helper for manual routes — wraps handler with auth check and firewall.
 * Pulls the request-scoped Drizzle db client off the Hono context and
 * threads it into buildFirewallConditions so relationship-role subqueries
 * (`via:` predicates) resolve at runtime.
 */
export async function withFirewall<T>(
  c: Context,
  handler: (ctx: AppContext, firewall: SQL | undefined) => Promise<T>
): Promise<Response | T> {
  const ctx = c.get('ctx') as AppContext;
  if (!ctx?.userId) {
    return c.json({
      error: 'Authentication required',
      layer: 'authentication',
      code: 'AUTH_MISSING',
      hint: 'Include Authorization header with Bearer token',
    }, 401);
  }
  const db = c.get('db' as never) as any;
  const firewall = buildFirewallConditions(ctx, db);
  return handler(ctx, firewall);
}

